SELECT 
    id, classify_id, title, model_name, model_name_zh, model_strength,
    addition_tag, hash, file_name, config, url, remark, type,
    is_open, belong_user_id, publish_status, crt_time, is_user_del, model_type
FROM model
WHERE belong_user_id = #{userId}

    AND model_type = #{modelType}


    AND is_user_del = #{isUserDel}

ORDER BY crt_time DESC

